ALTER TABLE cmd_actor_task_receipt ADD COLUMN leadership_allocation_id bigint UNIQUE REFERENCES camp_leadership_coordination_allocation(allocation_id), ADD COLUMN leadership_modifier smallint NOT NULL DEFAULT 0 CHECK(leadership_modifier>=0), ADD CHECK((leadership_allocation_id IS NULL)=(leadership_modifier=0));
CREATE OR REPLACE FUNCTION cmd_validate_actor_task_context() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE dice_total integer; expected_difficulty bigint; expected_frame bigint; expected_unit text; allocation camp_leadership_coordination_allocation%ROWTYPE;
BEGIN SELECT sum(result) INTO dice_total FROM cmd_random_draw WHERE command_id=NEW.command_id AND draw_group='task';
 IF NEW.check_total<>dice_total+NEW.skill_modifier+NEW.characteristic_modifier+NEW.difficulty_modifier+NEW.circumstance_modifier+NEW.fatigue_modifier+NEW.species_modifier+NEW.pace_modifier+NEW.simultaneous_action_modifier+NEW.leadership_modifier THEN RAISE EXCEPTION 'Task receipt total does not match its audited modifiers'; END IF;
 IF NEW.law_level IS NOT NULL THEN SELECT difficulty_rule_id INTO STRICT expected_difficulty FROM rule_law_level_difficulty WHERE law_level_range @> NEW.law_level::integer; IF expected_difficulty<>NEW.difficulty_rule_id THEN RAISE EXCEPTION 'Task difficulty does not match Law Level'; END IF; END IF;
 IF NEW.base_time_frame_rule_id IS NOT NULL THEN SELECT resolved.rule_id,resolved.increment_unit INTO STRICT expected_frame,expected_unit FROM rule_time_frame base JOIN rule_time_frame resolved ON resolved.display_order=base.display_order+NEW.time_frame_steps WHERE base.rule_id=NEW.base_time_frame_rule_id; IF expected_frame<>NEW.resolved_time_frame_rule_id OR expected_unit<>NEW.task_time_unit OR NOT EXISTS(SELECT 1 FROM cmd_random_draw WHERE command_id=NEW.command_id AND draw_group='task_time' AND draw_order=1 AND die_sides=6 AND result=NEW.task_time_roll) THEN RAISE EXCEPTION 'Task timing receipt does not match the published time-frame shift'; END IF; END IF;
 IF NEW.leadership_allocation_id IS NOT NULL THEN SELECT * INTO STRICT allocation FROM camp_leadership_coordination_allocation WHERE allocation_id=NEW.leadership_allocation_id; IF allocation.recipient_actor_id<>NEW.actor_id OR allocation.points<>NEW.leadership_modifier OR allocation.allocation_status<>'consumed' OR allocation.consumed_task_command_id<>NEW.command_id THEN RAISE EXCEPTION 'Task Leadership allocation mismatch'; END IF; END IF; RETURN NEW; END $$;
